import json
from datetime import datetime, timedelta

with open('/tmp/debug_state.json') as f:
    state = json.load(f)

customers = state.get('customers', {})
today = datetime(2026, 8, 2)
thirty_days = today + timedelta(days=30)

print("=== Customers with subscription_preferences ===")
for cid, c in customers.items():
    md = {m['key']: m['value'] for m in c.get('meta_data', [])}
    sub_pref = md.get('subscription_preferences', 'NOT_SET')
    print(f"ID:{cid} | {c['first_name']} {c['last_name']} | {c['email']} | sub_pref:{sub_pref}")

print("\n=== New products (launch within 30 days) ===")
products = state.get('products', {})
for pid, p in products.items():
    md = {m['key']: m['value'] for m in p.get('meta_data', [])}
    launch = md.get('launch_date', '')
    ptype = md.get('product_type', '')
    if ptype == 'new_product' and launch:
        ld = datetime.strptime(launch, '%Y-%m-%d')
        if today <= ld <= thirty_days:
            print(f"ID:{p['id']} | {p['name']} | launch:{launch}")

print("\n=== Discount products ===")
for pid, p in products.items():
    if p.get('on_sale') or p.get('sale_price'):
        md = {m['key']: m['value'] for m in p.get('meta_data', [])}
        ptype = md.get('product_type', '')
        print(f"ID:{p['id']} | {p['name']} | on_sale:{p['on_sale']} | sale_price:{p['sale_price']}")
PYEOF

